LINKS = {"a": "b", "b": "c", "c": "node9:/x/final"}
def follow(name):
    seen, hops = set(), []
    while name in LINKS and name not in seen:
        seen.add(name); hops.append(name); name = LINKS[name]
    return name, hops
final, hops = follow("a")
print(" -> ".join(hops), "=>", final)

