import time
CACHE, TTL = {}, 60
TABLE = {"f1": "node1:/a", "f2": "node2:/b"}
def resolve(name):
    now = time.time()
    if name in CACHE and now - CACHE[name][1] < TTL:
        return CACHE[name][0] + " (cached)"
    loc = TABLE[name]; CACHE[name] = (loc, now)
    return loc + " (fresh)"
print(resolve("f1")); print(resolve("f1"))

